<script src="https://cdn.jsdelivr.net/npm/@vladmandic/face-api@1.7.15/dist/face-api.js"></script><script src="https://cdn.jsdelivr.net/npm/@mediapipe/face_mesh/face_mesh.js"></script><script>
const video=document.getElementById('camera'),note=document.getElementById('cameraNote'),faceStatus=document.getElementById('faceStatus'),form=document.getElementById('attendanceForm'),blinkInput=document.getElementById('blinkVerified');
const attendanceAction='{{ $attendance?->check_in && !$attendance?->check_out ? 'check_out' : 'check_in' }}';let cameraStream=null,blinkInProgress=false,eyeWasClosed=false,lastBlinkAt=0;
const leftEye=[33,160,158,133,153,144],rightEye=[362,385,387,263,373,380];
const faceModelUrl='https://cdn.jsdelivr.net/npm/@vladmandic/face-api@1.7.15/model';
const referencePhotoUrls=@json(collect($referencePhotos)->map(fn ($photo) => asset('storage/face-references/'.$photo))->values());
let referenceDescriptors=[];
function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function eyeRatio(points,indexes){const a=points[indexes[0]],b=points[indexes[1]],c=points[indexes[2]],d=points[indexes[3]],e=points[indexes[4]],f=points[indexes[5]];return (distance(b,f)+distance(c,e))/(2*distance(a,d))}
async function loadReferenceFaces(){if(!referencePhotoUrls.length)throw new Error('Belum ada foto referensi wajah.');await faceapi.nets.tinyFaceDetector.loadFromUri(faceModelUrl);await faceapi.nets.faceLandmark68Net.loadFromUri(faceModelUrl);await faceapi.nets.faceRecognitionNet.loadFromUri(faceModelUrl);for(const url of referencePhotoUrls){const image=await faceapi.fetchImage(url);const result=await faceapi.detectSingleFace(image,new faceapi.TinyFaceDetectorOptions()).withFaceLandmarks().withFaceDescriptor();if(result)referenceDescriptors.push(result.descriptor)}if(!referenceDescriptors.length)throw new Error('Foto referensi tidak dapat dibaca.');}
async function verifyFace(){const result=await faceapi.detectSingleFace(video,new faceapi.TinyFaceDetectorOptions()).withFaceLandmarks().withFaceDescriptor();if(!result)return false;const bestDistance=Math.min(...referenceDescriptors.map(reference=>faceapi.euclideanDistance(result.descriptor,reference)));return bestDistance<.55}
async function sendAttendance(){if(blinkInProgress)return;blinkInProgress=true;blinkInput.value='0';faceStatus.textContent='Memeriksa kecocokan wajah...';faceStatus.className='alert';if(!await verifyFace()){blinkInProgress=false;faceStatus.textContent='Wajah tidak sesuai dengan foto akun. Absensi dibatalkan.';faceStatus.className='alert error';return}blinkInput.value='1';faceStatus.textContent='Wajah cocok. Mengambil lokasi untuk absen '+(attendanceAction==='check_in'?'masuk':'pulang')+'...';faceStatus.className='alert success';if(!navigator.geolocation){blinkInProgress=false;faceStatus.textContent='Browser tidak mendukung GPS.';return}navigator.geolocation.getCurrentPosition(position=>{document.getElementById('attendanceAction').value=attendanceAction;document.getElementById('latitude').value=position.coords.latitude;document.getElementById('longitude').value=position.coords.longitude;document.getElementById('accuracy').value=position.coords.accuracy;form.submit()},()=>{blinkInProgress=false;blinkInput.value='0';faceStatus.textContent='Lokasi tidak tersedia. Aktifkan GPS lalu kedipkan kembali.';faceStatus.className='alert error'},{enableHighAccuracy:true,timeout:20000,maximumAge:0})}
async function startCamera(){try{faceStatus.textContent='Memuat verifikasi wajah...';await loadReferenceFaces();cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});video.srcObject=cameraStream;note.textContent='Wajah aktif. Berkediplah satu kali untuk absensi otomatis.';const mesh=new FaceMesh({locateFile:file=>'https://cdn.jsdelivr.net/npm/@mediapipe/face_mesh/'+file});mesh.setOptions({maxNumFaces:1,refineLandmarks:true,minDetectionConfidence:.7,minTrackingConfidence:.7});mesh.onResults(results=>{if(blinkInProgress)return;if(!results.multiFaceLandmarks?.length){faceStatus.textContent='Wajah belum terdeteksi. Posisikan wajah di tengah kamera.';faceStatus.className='alert';return}const landmarks=results.multiFaceLandmarks[0],ratio=(eyeRatio(landmarks,leftEye)+eyeRatio(landmarks,rightEye))/2;faceStatus.textContent='Wajah terdeteksi. Kedipan otomatis aktif.';faceStatus.className='alert success';if(ratio<.2)eyeWasClosed=true;if(eyeWasClosed&&ratio>.24&&Date.now()-lastBlinkAt>1500){eyeWasClosed=false;lastBlinkAt=Date.now();sendAttendance()}});async function scan(){if(video.readyState>=2)await mesh.send({image:video});requestAnimationFrame(scan)}scan()}catch(error){note.textContent='Kamera atau foto referensi tidak dapat diakses.';faceStatus.textContent=error.message;faceStatus.className='alert error'}}startCamera();
</script>
